#include <vector>

class Solution {
public:
    long long countSubarrays(std::vector<int>& nums, int minK, int maxK) {
        long long total = 0;
        long long curr = 0;
        for (int x : nums) {
            if (x >= minK && x <= maxK) {
                curr++;
                total += curr;
            } else {
                curr = 0;
            }
        }
        return total;
    }
};

class Solution {
    public long countSubarrays(int[] nums, int minK, int maxK) {
        long ans = 0;
        int minPos = -1, maxPos = -1, badPos = -1;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] < minK || nums[i] > maxK) badPos = i;
            if (nums[i] == minK) minPos = i;
            if (nums[i] == maxK) maxPos = i;
            int validStart = Math.min(minPos, maxPos);
            if (validStart > badPos) ans += (validStart - badPos);
        }
        return ans;
    }
}

var countSubarrays = function(nums, minK, maxK) {
    let ans = 0;
    let minPos = -1, maxPos = -1, badPos = -1;
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] < minK || nums[i] > maxK) badPos = i;
        if (nums[i] === minK) minPos = i;
        if (nums[i] === maxK) maxPos = i;
        const validStart = Math.min(minPos, maxPos);
        if (validStart > badPos) ans += (validStart - badPos);
    }
    return ans;
